import PlayGame from './PlayGame.js';


export default class States extends PIXI.Container {

    constructor() {
        super();

        this.stateIDMap = {
            // this is the current state
            preload: Preload,

            // this is the first one after preload
            mainMenu: MainMenu,

            // this can be any number
            100: PlayGame,
        }
    }

    preload() {
        SceneManager.queueState('preload');
    }

    mainMenu() {
        SceneManager.queueState('mainMenu');
    }

    playGame() {
        SceneManager.queueState(100);
    }
}
